import type { RadioGroupProps } from "./radio-group.types";
import type { CSSObject } from "@emotion/react";
import type { ComponentStyleVariantConfig, Theme } from "@types";

import * as RadixRadioGroup from "@radix-ui/react-radio-group";
import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "RadioGroup";

// Generate child element class names for the component, should match available style slots
export const RadioGroupClasses = {
  root: "exp-textura_radio-group",
  item: "exp-textura_radio-group_item",
  itemWrapper: "exp-textura_radio-group_item_wrapper",
  itemLabel: "exp-textura_radio-group_item_label",
  indicator: "exp-textura_radio-group_indicator",
  sm: "exp-textura_radio-group_sm",
};

const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
  critical: {
    item: {
      border: `${theme.toRem(theme.border.width.md)} solid ${theme.inputSelect.radio.off.critical.color.content.enabled}`,
    },
    itemHover: {
      borderColor: theme.inputSelect.radio.off.critical.color.content.hover,
    },
    itemChecked: {
      borderColor: theme.inputSelect.radio.on.critical.color.content.enabled,
      backgroundColor: theme.inputSelect.radio.on.critical.color.background.enabled,
    },
    itemCheckedHover: {
      borderColor: theme.inputSelect.radio.on.critical.color.content.hover,
      backgroundColor: theme.inputSelect.radio.on.critical.color.background.hover,
    },
    itemCheckedPressed: {
      borderColor: theme.inputSelect.radio.on.critical.color.content.pressed,
      backgroundColor: theme.inputSelect.radio.on.critical.color.background.pressed,
    },
    itemDisabled: {
      borderColor: theme.inputSelect.radio.off.critical.color.content.disabled,
    },
    itemPressed: {
      borderColor: theme.inputSelect.radio.off.critical.color.content.pressed,
    },
    indicatorAfter: {
      backgroundColor: theme.inputSelect.radio.on.critical.color.content.enabled,
    },
    indicatorAfterHover: {
      backgroundColor: theme.inputSelect.radio.on.critical.color.content.hover,
    },
    indicatorAfterPressed: {
      backgroundColor: theme.inputSelect.radio.on.critical.color.content.pressed,
    },
    indicatorAfterDisabled: {
      backgroundColor: theme.inputSelect.radio.on.critical.color.content.disabled,
    },
  },
  inverse: {
    item: {
      backgroundColor: theme.inputSelect.radio.off.inverse.color.background.enabled,
      border: `${theme.toRem(theme.border.width.md)} solid ${theme.inputSelect.radio.off.inverse.color.content.enabled}`,
    },
    itemHover: {
      borderColor: theme.inputSelect.radio.off.inverse.color.content.hover,
    },
    itemChecked: {
      borderColor: theme.inputSelect.radio.on.inverse.color.content.enabled,
      backgroundColor: theme.inputSelect.radio.on.inverse.color.background.enabled,
    },
    itemCheckedHover: {
      borderColor: theme.inputSelect.radio.on.inverse.color.content.hover,
      backgroundColor: theme.inputSelect.radio.on.inverse.color.background.hover,
    },
    itemCheckedPressed: {
      borderColor: theme.inputSelect.radio.on.inverse.color.content.pressed,
      backgroundColor: theme.inputSelect.radio.on.inverse.color.background.pressed,
    },
    itemDisabled: {
      borderColor: theme.inputSelect.radio.off.inverse.color.content.disabled,
    },
    itemPressed: {
      borderColor: theme.inputSelect.radio.off.inverse.color.content.pressed,
    },
    itemLabel: {
      color: theme.inputSelect.radio.off.inverse.color.content.enabled,
    },
    itemLabelDisabled: {
      color: theme.inputSelect.radio.off.inverse.color.content.disabled,
    },
    indicatorAfter: {
      backgroundColor: theme.inputSelect.radio.on.inverse.color.content.enabled,
    },
    indicatorAfterHover: {
      backgroundColor: theme.inputSelect.radio.on.inverse.color.content.hover,
    },
    indicatorAfterPressed: {
      backgroundColor: theme.inputSelect.radio.on.inverse.color.content.pressed,
    },
    indicatorAfterDisabled: {
      backgroundColor: theme.inputSelect.radio.on.inverse.color.content.disabled,
    },
  },
});

const generateStyles = (props: RadioGroupProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<RadioGroupProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    all: "unset",
    display: "flex",
    flexDirection: "column",
    backgroundColor: undefined,
    color: theme.color.content.default,
    gap: theme.toRem(theme.spacing[12]),
    ...theme.typography.body.md,

    "&[data-disabled]": {
      color: theme.color.content.disabled,
      ...styleSlots?.disabled,
    },

    "&[data-orientation='horizontal']": {
      flexDirection: "row",
      gap: theme.toRem(theme.spacing[16]),
      ...styleSlots?.horizontal,
    },

    [`&.${RadioGroupClasses.sm}`]: {
      gap: theme.toRem(theme.spacing[8]),
      [`.${RadioGroupClasses.itemLabel}`]: {
        ...theme.typography.body.sm,
        ...styleSlots?.itemLabelSm,
      },
      ...styleSlots?.sm,
    },

    [`.${RadioGroupClasses.itemWrapper}`]: {
      display: "flex",
      flexDirection: "row",
      alignItems: "center",
      ...styleSlots?.itemWrapper,
    },

    [`.${RadioGroupClasses.item}`]: {
      backgroundColor: theme.inputSelect.radio.off.default.color.background.enabled,
      border: `${theme.toRem(theme.border.width.md)} solid ${theme.inputSelect.radio.off.default.color.content.enabled}`,
      display: "flex",
      justifyContent: "center",
      alignItems: "center",
      width: theme.toRem(theme.spacing[16]),
      height: theme.toRem(theme.spacing[16]),
      borderRadius: "100%",

      "&:focus-visible": {
        outline: "none",
        ...styleSlots?.itemFocus,
      },

      "&:hover:not([disabled])": {
        borderColor: theme.inputSelect.radio.off.default.color.content.hover,
        ...styleSlots?.itemHover,
      },

      "&:active:not([disabled])": {
        borderColor: theme.inputSelect.radio.off.default.color.content.pressed,
        ...styleSlots?.itemPressed,
      },

      "&[aria-checked='true']": {
        borderColor: theme.inputSelect.radio.on.default.color.content.enabled,
        backgroundColor: theme.inputSelect.radio.on.default.color.background.enabled,

        "&:hover:not([disabled])": {
          borderColor: theme.inputSelect.radio.on.default.color.content.hover,
          backgroundColor: theme.inputSelect.radio.on.default.color.background.hover,
          [`.${RadioGroupClasses.indicator}`]: {
            "&:after": {
              backgroundColor: theme.inputSelect.radio.on.default.color.content.hover,
              ...styleSlots?.indicatorAfterHover,
            },
          },
          ...styleSlots?.itemCheckedHover,
        },

        "&:active:not([disabled])": {
          borderColor: theme.inputSelect.radio.on.default.color.content.pressed,
          backgroundColor: theme.inputSelect.radio.on.default.color.background.pressed,
          [`.${RadioGroupClasses.indicator}`]: {
            "&:after": {
              backgroundColor: theme.inputSelect.radio.on.default.color.content.pressed,
              ...styleSlots?.indicatorAfterPressed,
            },
          },
          ...styleSlots?.itemCheckedPressed,
        },
        ...styleSlots?.itemChecked,
      },

      "&[disabled]": {
        border: `${theme.toRem(theme.border.width.md)} solid ${theme.inputSelect.radio.off.default.color.content.disabled}`,
        cursor: "not-allowed",
        [`.${RadioGroupClasses.indicator}`]: {
          "&:after": {
            backgroundColor: theme.inputSelect.radio.on.default.color.content.disabled,
            ...styleSlots?.indicatorAfterDisabled,
          },
        },
        ...styleSlots?.itemDisabled,
      },

      ...styleSlots?.item,
    },

    [`.${RadioGroupClasses.indicator}`]: {
      width: theme.toRem(theme.spacing[8]),
      height: theme.toRem(theme.spacing[8]),
      "&:after": {
        content: '""',
        display: "block",
        width: theme.toRem(theme.spacing[8]),
        height: theme.toRem(theme.spacing[8]),
        backgroundColor: theme.inputSelect.radio.on.default.color.content.enabled,
        borderRadius: "50%",
        ...styleSlots?.indicatorAfter,
      },
      ...styleSlots?.indicator,
    },

    [`.${RadioGroupClasses.itemLabel}`]: {
      color: theme.color.content.default,
      paddingInlineStart: theme.toRem(theme.spacing[8]),
      display: "flex",
      alignItems: "center",
      [`&[data-disabled]`]: {
        color: theme.inputSelect.radio.off.default.color.content.disabled,
        ...styleSlots?.itemLabelDisabled,
      },
      ...styleSlots?.itemLabel,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledRadioGroup = styled(RadixRadioGroup.Root, {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<RadioGroupProps>((props) => generateStyles(props));
